export function machineSettings(settings){return `<h3>Flight & controller</h3>
 <label class="settingRow">Drone stick layout<select data-setting="droneStickLayout"><option value="mode2" ${settings.droneStickLayout==='mode2'?'selected':''}>Mode 2 / lift + yaw, pitch + roll</option><option value="classic" ${settings.droneStickLayout==='classic'?'selected':''}>Classic / move + look</option></select></label>
 <label class="settingRow">Manual drone flight<select data-setting="droneFlight"><option value="stabilized" ${settings.droneFlight==='stabilized'?'selected':''}>Stabilized / hover assist</option><option value="acro" ${settings.droneFlight==='acro'?'selected':''}>Acro / attitude & thrust</option></select></label>
 <p class="hint">Mode 2 (touch / Xbox): left stick up/down = lift, left/right = yaw. Right stick = forward/strafe in Stabilized, pitch/roll in Acro. Acro right-stick up pitches the nose down. Centered lift supplies hover thrust, not automatic altitude hold when tilted; Acro does not level itself. Classic keeps move/look and RISE/DESCEND or D-pad lift. Keyboard is unchanged: W/S nose drive, A/D strafe or roll, mouse/arrows pitch/yaw, Space/Shift lift. Use HOLD to recover. Touch starts in Stabilized.</p>
 <label class="settingRow">Xbox / standard controller<input type="checkbox" data-setting="gamepad" ${settings.gamepad?'checked':''}></label>
 <label class="settingRow">Controller invert Y<input type="checkbox" data-setting="gamepadInvert" ${settings.gamepadInvert?'checked':''}></label>
 ${[['gamepadDeadzone','Stick deadzone',.05,.4,.01],['gamepadSensitivity','Controller sensitivity',.25,2.5,.05]].map(([id,label,min,max,step])=>`<label class="settingRow">${label}<input type="range" data-setting="${id}" min="${min}" max="${max}" step="${step}" value="${settings[id]}"><output>${settings[id]}</output></label>`).join('')}
 <div class="padGuide"><b>XBOX / STANDARD MAPPING</b><p>LS move · RS look · LT brake · RT motor assist<br>A use/select · B dismount/back · X scan · Y pack<br>LB camera · RB drone · View map · Start pause<br>LS click pedal · RS click pulse · D-pad ←/→ drone command<br>Menus: LS / D-pad focus · A select · B close. Left/right adjusts sliders.</p></div>`;}
